#include <vector>

// Correct: every choice is undone before the next one is tried.
void subsets(const std::vector<int>& items, int start,
             std::vector<int>& current,
             std::vector<std::vector<int>>& out) {
    out.push_back(current);          // copy, not a reference

    for (int i = start; i < (int)items.size(); i++) {
        current.push_back(items[i]);         // choose
        subsets(items, i + 1, current, out); // explore
        current.pop_back();                  // un-choose
    }
}
